CREATE OR REPLACE FUNCTION public.protect_telegram_profile_link() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF current_user <> 'postgres' AND coalesce(auth.role(), '') <> 'service_role' THEN IF TG_OP = 'INSERT' THEN IF NEW.telegram_user_id IS NOT NULL OR NEW.telegram_username IS NOT NULL THEN RAISE EXCEPTION 'Telegram identity can only be set by the registration service'; END IF; ELSIF NEW.telegram_user_id IS DISTINCT FROM OLD.telegram_user_id OR NEW.telegram_username IS DISTINCT FROM OLD.telegram_username THEN RAISE EXCEPTION 'Telegram identity can only be changed by the registration service'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_telegram_profile_link_insert BEFORE INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_telegram_profile_link();